-- ==============================================================================
-- Migration: 20261023000100_central_catalogue.sql
-- Description: Central Product Catalogue (407 Canonical Bengali Wholesale Products)
-- Multi-Tenancy: Shared read-only catalogue with tenant-scoped product adoption
-- ==============================================================================

-- 1. Create central catalogue master table
create table if not exists public.central_catalogue (
  id uuid primary key default gen_random_uuid(),
  code text unique not null check (code ~ '^CAT-[0-9]{3}$'),
  sequence text unique not null check (sequence ~ '^[0-9]{3}$'),
  name_bn text not null check (length(btrim(name_bn)) between 1 and 200),
  category_bn text not null check (length(btrim(category_bn)) between 1 and 100),
  packaging_description text check (packaging_description is null or length(btrim(packaging_description)) between 1 and 100),
  brand_name text check (brand_name is null or length(btrim(brand_name)) between 1 and 100),
  aliases_bn text[] not null default '{}',
  search_text text not null default '',
  image_path text check (image_path is null or length(btrim(image_path)) <= 255),
  image_status text not null default 'pending' check (image_status in ('pending', 'verified', 'rejected')),
  verification_status text not null default 'pending' check (verification_status in ('pending', 'verified', 'rejected')),
  is_active boolean not null default true,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

-- Index for category listing and active status filtering
create index if not exists central_catalogue_active_name_idx
  on public.central_catalogue (is_active, name_bn varchar_pattern_ops);
create index if not exists central_catalogue_category_idx
  on public.central_catalogue (category_bn);

-- 2. Link tenant products to central catalogue
alter table public.products
  add column if not exists catalogue_id uuid
    references public.central_catalogue(id) on delete restrict;

-- Ensure a business cannot adopt the same catalogue item more than once
create unique index if not exists products_business_catalogue_uidx
  on public.products (business_id, catalogue_id)
  where catalogue_id is not null;

-- 3. Row Level Security and Permissions
alter table public.central_catalogue enable row level security;

-- Authenticated tenants have read-only access to view and search central catalogue
drop policy if exists central_catalogue_read on public.central_catalogue;
create policy central_catalogue_read on public.central_catalogue
  for select to authenticated using (true);

-- Least privilege: revoke all write permissions from client roles
revoke all on public.central_catalogue from public, anon, authenticated;
grant select on public.central_catalogue to authenticated;

